  "host_observations": [
    {"host": "WS-IT-19.corp.local", "role": "endpoint", "user": "d.romano", "victim_ip": "10.40.55.119", "target_dc": "DC-CORP-01.corp.local", "first_seen": "2033-07-14T11:48:08+0000", "last_seen": "2033-07-14T11:53:00+0000"}
